-- Deterministic future-dated demo activities for the hackathon catalog.
on conflict (dedupe_key) do update set
    name = excluded.name, description = excluded.description, location = excluded.location,
    start_at = excluded.start_at, end_at = excluded.end_at, cost = excluded.cost,
    info_link = excluded.info_link, signup_link = excluded.signup_link, tags = excluded.tags,
    suitability_score = excluded.suitability_score, engagement_score = excluded.engagement_score,
    total_score = excluded.total_score, status = excluded.status, updated_at = now();
